\usepackage[font=small,labelfont=bf,width=0.92\textwidth]{caption}
\definecolor{cDiv}{HTML}{1B4F72}
\definecolor{cFuse}{HTML}{7B241C}
\definecolor{cWork}{HTML}{145A32}
\definecolor{cIdle}{HTML}{5D6D7E}
\definecolor{cExact}{HTML}{D6EAF8}
