        Region {
            split: si,
            fuse: fj,
            substantial: inner.iter().copied().any(is_work),
            interior: inner.into_iter().collect(),
        }
    }).collect();
    (regions, un_split, un_fuse)
}

/// Glyphs strictly inside a region, walking forward around the cycle.""")
